package com.bplus.share;
import android.app.*;import android.content.*;import android.net.Uri;import android.view.*;import org.json.*;import java.util.*;
public final class FileSelection implements ActionMode.Callback{
 private final Activity a;private final String thread;private final Runnable refresh;private final Set<String> selected=new HashSet<>();private ActionMode mode;
 public FileSelection(Activity a,String thread,Runnable refresh){this.a=a;this.thread=thread;this.refresh=refresh;}
 static String key(JSONObject m){return m.optString("id",m.optString("uri")+"|"+m.optString("name")+"|"+m.optLong("ts"));}
 public boolean active(){return mode!=null;}public boolean has(JSONObject m){return selected.contains(key(m));}
 public void toggle(JSONObject m){if(mode==null)mode=a.startActionMode(this);String k=key(m);if(!selected.add(k))selected.remove(k);if(selected.isEmpty()&&mode!=null)mode.finish();else if(mode!=null)mode.setTitle(String.valueOf(selected.size()));refresh.run();}
 public boolean onCreateActionMode(ActionMode m,Menu menu){menu.add(0,1,0,a.getString(R.string.send_now)).setIcon(android.R.drawable.ic_menu_send).setShowAsAction(MenuItem.SHOW_AS_ACTION_ALWAYS);menu.add(0,2,1,a.getString(R.string.remove_message)).setIcon(android.R.drawable.ic_menu_delete).setShowAsAction(MenuItem.SHOW_AS_ACTION_ALWAYS);menu.add(0,3,2,a.getString(R.string.select_all)).setIcon(android.R.drawable.ic_menu_agenda).setShowAsAction(MenuItem.SHOW_AS_ACTION_ALWAYS);return true;}
 public boolean onPrepareActionMode(ActionMode m,Menu menu){return false;}
 private ArrayList<JSONObject> chosen(){ArrayList<JSONObject> out=new ArrayList<>();JSONArray t=Store.thread(thread);for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m!=null&&m.optString("kind").equals("file")&&selected.contains(key(m)))out.add(m);}return out;}
 public boolean onActionItemClicked(ActionMode m,MenuItem item){if(item.getItemId()==3){JSONArray t=Store.thread(thread);for(int i=0;i<t.length();i++){JSONObject file=t.optJSONObject(i);if(file!=null&&file.optString("kind").equals("file"))selected.add(key(file));}m.setTitle(String.valueOf(selected.size()));refresh.run();return true;}ArrayList<JSONObject> files=chosen();if(item.getItemId()==1){JSONArray peers=Store.peers();String[] names=new String[peers.length()];for(int i=0;i<names.length;i++)names[i]=peers.optJSONObject(i).optString("name");new AlertDialog.Builder(a).setTitle(R.string.send_files).setItems(names,(d,n)->new AlertDialog.Builder(a).setMessage(a.getString(R.string.send_selected_confirm,files.size(),names[n])).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.send_now,(confirm,k)->{JSONObject peer=peers.optJSONObject(n);new Thread(()->{int ok=0;for(JSONObject f:files)if(FileCards.available(a,f)&&TransferService.sendToPeer(peer,FileCards.uri(f),f.optString("name"),f.optLong("size")))ok++;final int sent=ok;a.runOnUiThread(()->android.widget.Toast.makeText(a,a.getString(R.string.forward_result,sent,files.size()),1).show());}).start();m.finish();}).show()).show();return true;}
 if(item.getItemId()==2){new AlertDialog.Builder(a).setTitle(R.string.remove_message).setItems(new String[]{a.getString(R.string.remove_cards_only),a.getString(R.string.delete_local_files)},(d,n)->new AlertDialog.Builder(a).setMessage(a.getString(n==0?R.string.remove_cards_note:R.string.delete_files_note,files.size())).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.remove_message,(c,k)->{if(n==0){synchronized(Store.class){JSONArray old=Store.thread(thread),keep=new JSONArray();for(int i=0;i<old.length();i++){JSONObject f=old.optJSONObject(i);if(f!=null&&!selected.contains(key(f)))keep.put(f);}Store.saveThread(thread,keep);}}else{int failed=0;Set<String> done=new HashSet<>();for(JSONObject f:files){Uri u=FileCards.uri(f);if(u==null){failed++;continue;}if(!done.add(u.toString()))continue;try{if(!"content".equals(u.getScheme())||a.getContentResolver().delete(u,null,null)==0)failed++;}catch(Exception e){failed++;}}android.widget.Toast.makeText(a,a.getString(R.string.delete_result,failed),1).show();}m.finish();refresh.run();}).show()).show();return true;}return false;}
 public void onDestroyActionMode(ActionMode m){mode=null;selected.clear();refresh.run();}
}
